import * as p from '@clack/prompts';
import fs from 'fs/promises';
import path from 'path';
import pc from 'picocolors';
import { getBootstrapInfo } from '../api/control-plane.js';
import { ControlPlaneError } from '../api/control-plane-error.js';
import { FigmaApiError } from '../api/figma-api.js';
import { tryGetCredential } from '../auth/oauth-flow.js';
import { getValidProjectToken, ProjectTokenError } from '../auth/project-token.js';
import { getTokenStore } from '../auth/token-store.js';
import { getInfraEnvironment, getProjectNotFoundMessage } from '../constants.js';
import { writeAgentConfigFiles } from '../lib/write-agent-config.js';
import { ensureGitignore } from '../utils/config.js';
import { addOrUpdateEnvVar, commentOutEnvVar, removeEnvVar } from '../utils/env-management.js';
import { isDebug } from '../utils/is-debug.js';
import { applyLambdaModifications } from '../utils/lambda-config.js';
import * as log from '../utils/log.js';
import { detectPackageManagerFromEnvironment, getRunCommand, resolvePackageManager } from '../utils/package-manager.js';
import { displayManualInstructions, ensurePayloadFigmaConfig } from '../utils/payload-config-modifier.js';
import { generateImportMap, generateTypes } from '../utils/payload-generate.js';
import { ensurePnpmWorkspace } from '../utils/pnpm-builds.js';
import { detectPayloadProject, hasRequiredDependencies, initializeGitRepo, installDependencies, isInProjectDirectory, scaffoldProject, validatePayloadVersion } from '../utils/project.js';
import { resolveEnvironment } from '../utils/resolve-environment.js';
import { checkForUpdates, getOwnVersion } from '../utils/version-check.js';
import { detectProjectResourceType } from './detect-project-resource-type.js';
import { loginCommand } from './login.js';
import { promptToCreateProject } from './prompt-to-create-project.js';
import { writeProjectConfiguration } from './write-project-configuration.js';
import { cacheAllEnvironments } from '../utils/cache-bootstrap.js';
import { DEFAULT_TEMPLATE_SOURCE } from '../utils/download-template.js';
import { parseTemplateSpec, TemplateSpecParseError } from '../utils/parse-template-spec.js';
import { ensurePayloadSecret } from '../utils/payload-secret.js';
async function removePayloadSecretFromEnv(projectDir) {
    // New-project flow: the scaffold owns .env, so any PAYLOAD_SECRET carried
    // over from a template is not a value the developer set. Remove it
    // outright to keep the scaffolded file clean.
    const removed = await removeEnvVar(projectDir, 'PAYLOAD_SECRET');
    if (!removed) {
        return;
    }
    p.log.warn(pc.yellow('⚠ Removed PAYLOAD_SECRET from .env. The Figma platform owns this value; a local ' + 'copy would silently diverge from the deployed secret and cause encrypted data ' + '(API keys, auth tokens) to fail decryption in production.'));
}
async function commentOutPayloadSecretInEnv(projectDir) {
    // Existing-project flow: the developer's .env may hold a PAYLOAD_SECRET
    // they need for another system or environment. Comment out rather than
    // delete so the value survives and they can uncomment / relocate it.
    const changed = await commentOutEnvVar(projectDir, 'PAYLOAD_SECRET', 'disabled by @payloadcms/figma: platform owns PAYLOAD_SECRET');
    if (!changed) {
        return;
    }
    p.log.warn(pc.yellow('⚠ Commented out PAYLOAD_SECRET in .env. The Figma platform owns this value; a ' + 'local copy would silently diverge from the deployed secret and cause encrypted ' + 'data (API keys, auth tokens) to fail decryption in production.'));
}
async function maybeEnsurePayloadSecret(args) {
    if (!args.credential || !args.resolvedEnv) {
        return false;
    }
    try {
        await ensurePayloadSecret({
            credential: args.credential,
            projectInfo: {
                environmentName: args.resolvedEnv.name,
                projectId: args.cmsResourceId
            },
            tenantInstanceId: args.resolvedEnv.tenantInstanceId,
            tokenStore: args.tokenStore,
            // Re-init is the explicit recovery path after platform secret rotation.
            refresh: true
        });
        log.debug('PAYLOAD_SECRET cached in TokenStore');
        return true;
    } catch (err) {
        // Preserve the existing cache and .env fallback until a refresh succeeds.
        const message = err instanceof Error ? err.message : 'Unknown error';
        p.log.warn(pc.yellow(`⚠ Could not fetch PAYLOAD_SECRET (${message}). Existing secrets were preserved. Re-run init to retry.`));
        return false;
    }
}
async function maybeWriteAgentConfigFiles(args) {
    if (args.noAgent) {
        return;
    }
    try {
        await writeAgentConfigFiles({
            projectDir: args.projectDir
        });
    } catch (err) {
        p.log.warn(pc.yellow(`⚠ Could not write AI agent config (${err instanceof Error ? err.message : String(err)}). Continuing.`));
    }
}
/** Generate the admin import map and Payload types so the scaffold builds clean. */ async function runProjectCodegen(args) {
    await runPayloadGenerate({
        ...args,
        artifact: 'import map',
        command: 'generate:importmap',
        generate: generateImportMap
    });
    await runPayloadGenerate({
        ...args,
        artifact: 'types',
        command: 'generate:types',
        generate: generateTypes
    });
}
/** Non-fatal: on failure, warn with the command to run later. */ async function runPayloadGenerate(args) {
    args.spinner.start(`Generating ${args.artifact}...`);
    const result = await args.generate(args.projectDir);
    const capitalized = args.artifact.charAt(0).toUpperCase() + args.artifact.slice(1);
    if (result.ok) {
        args.spinner.stop(pc.green(`✓ ${capitalized} generated`));
        return;
    }
    args.spinner.stop(pc.yellow(`⚠ Could not generate ${args.artifact}`));
    p.log.warn(pc.yellow(`Run '${getRunCommand(args.packageManager)} ${args.command}' later. ${result.error}`));
}
/**
 * Generate and store project token for a content system
 * Non-blocking - will show warning but not exit on failure
 * Only shows feedback if DEBUG mode is enabled, otherwise runs silently
 *
 * @param tokenStore - Token store instance
 * @param contentSystemId - Content System ID to generate token for
 * @param spinner - Clack spinner instance for status updates (only used in debug mode)
 */ async function generateProjectTokenWithFeedback(tokenStore, contentSystemId, spinner, projectInfo) {
    if (isDebug()) {
        spinner.start('Generating project token...');
    }
    try {
        const projectToken = await getValidProjectToken({
            projectInfo,
            tenantId: contentSystemId,
            tokenStore
        });
        if (isDebug()) {
            if (projectToken) {
                spinner.stop(pc.green('✓ Project token generated'));
            } else {
                spinner.stop(pc.yellow('⚠ Project token not generated (authentication required)'));
            }
        }
    } catch (error) {
        if (isDebug()) {
            spinner.stop(pc.yellow('⚠ Project token generation failed'));
        }
        // Always show failures, even without debug
        if (error instanceof ProjectTokenError || error instanceof FigmaApiError) {
            log.warning(error.message);
            p.note('Project token is used for authenticating to the Content API.\nYou can continue without it, but may need to regenerate later.', 'Note');
        } else {
            log.warning(`Unable to retrieve project token: ${error instanceof Error ? error.message : 'Unknown error'}`);
        }
    // Don't exit - token generation failure shouldn't block initialization
    }
}
/**
 * Handle the `init` command
 *
 * Sets up a project by:
 * 1. Checking authentication
 * 2. Detecting/scaffolding Payload project
 * 3. Fetching tenant details
 * 4. Storing configuration
 *
 * @param options - Command options
 */ export async function initCommand(options) {
    // Check for mismatched version (non-blocking)
    const currentVersion = await getOwnVersion();
    await checkForUpdates(currentVersion);
    // Check authentication
    const tokenStore = getTokenStore();
    const s = p.spinner();
    let credential = null;
    if (options.skipAuth) {
        // Skip authentication for testing/development
        p.log.warn(pc.yellow('Skipping authentication (--skip-auth mode)'));
    } else {
        // Check for valid cached tokens first (no API call needed)
        if (!tokenStore.hasValidOauthToken()) {
            // Need to refresh or authenticate - show spinner for API call
            s.start('Checking authentication...');
            credential = await tryGetCredential(tokenStore);
            if (!credential) {
                s.stop('Authentication required to continue');
                await loginCommand({
                    showNextSteps: false
                });
                credential = await tryGetCredential(tokenStore);
                if (!credential) {
                    p.log.error('Authentication failed');
                    process.exit(1);
                }
            } else {
                s.stop(pc.green('✓ Authenticated'));
            }
        }
    }
    if (!options.skipAuth && !credential) {
        credential = await tryGetCredential(tokenStore);
    }
    // Note: We no longer check for figma.config.json here
    // Instead, the AST detection will check if figma object already exists in payload.config.ts
    // and skip modification if it does (unless --force is used)
    // Parse --template spec early so malformed values abort before any I/O
    let templateSource;
    if (options.template) {
        try {
            templateSource = parseTemplateSpec(options.template);
        } catch (error) {
            const message = error instanceof TemplateSpecParseError ? error.message : 'Invalid --template value';
            p.log.error(pc.red(`✗ ${message}`));
            p.note('Format: [<owner>/<repo>#]<ref>:<template-path>\n' + 'Examples:\n' + '  blank\n' + '  main:website\n' + '  myorg/payload-fork#feat-x:templates/custom', 'Template spec');
            process.exit(1);
        }
    }
    // Step 3: Resolve or create the CMS project
    log.debug('Configuring Project...');
    const hasPackageJson = await isInProjectDirectory();
    const resourceType = await detectProjectResourceType();
    const isInProject = hasPackageJson || resourceType === 'vite';
    let projectDirectory = process.cwd();
    if (isInProject && resourceType !== 'vite' && !options.id) {
        const projectInfo = await detectPayloadProject();
        if (!projectInfo.hasPayload) {
            p.log.warn(pc.yellow('⚠ Payload was not detected in this project'));
            p.note('Run this command in a directory without an existing project or in an existing Payload project.', 'Action Required');
            process.exit(1);
        }
        if (projectInfo.payloadVersion && !validatePayloadVersion(projectInfo.payloadVersion)) {
            p.log.warn(pc.yellow(`Payload version ${projectInfo.payloadVersion} detected. Version 4.x or newer is required.`));
            p.note('Upgrade to Payload 4.x or newer before continuing', 'Action Required');
            process.exit(1);
        }
    }
    if (!isInProject) {
        let projectPath;
        if (options.name) {
            projectPath = options.name;
        } else {
            const projectPathInput = await p.text({
                initialValue: './',
                message: 'Enter path to create project:',
                placeholder: './my-cms-project',
                validate: (value)=>{
                    if (!value) {
                        return 'Path is required';
                    }
                    return undefined;
                }
            });
            if (p.isCancel(projectPathInput)) {
                p.cancel('Operation cancelled');
                process.exit(0);
            }
            projectPath = projectPathInput;
        }
        projectDirectory = path.resolve(process.cwd(), projectPath);
        const projectName = path.basename(projectDirectory);
        const packageManager = detectPackageManagerFromEnvironment();
        try {
            await fs.mkdir(projectDirectory, {
                recursive: true
            });
        } catch (error) {
            p.log.error(`Failed to create directory: ${error instanceof Error ? error.message : 'Unknown error'}`);
            process.exit(1);
        }
        const resolvedSource = {
            ...DEFAULT_TEMPLATE_SOURCE,
            ...templateSource
        };
        s.start(`Downloading template "${resolvedSource.templatePath}" from ` + `${resolvedSource.owner}/${resolvedSource.repo}@${resolvedSource.ref}...`);
        try {
            await scaffoldProject(projectDirectory, projectName, packageManager, templateSource, options.payloadVersion);
            s.stop(pc.green('✓ Template downloaded'));
            s.start('Installing dependencies...');
            await installDependencies(projectDirectory, packageManager);
            s.stop(pc.green('✓ Dependencies installed'));
        } catch (error) {
            s.stop(pc.red('✗ Failed'));
            log.error(error instanceof Error ? error.message : 'Unknown error');
            process.exit(1);
        }
    }
    let cmsResourceId = options.id;
    if (!cmsResourceId) {
        if (!credential) {
            p.log.error('Authentication is required to create a project');
            process.exit(1);
        }
        const createdProject = await promptToCreateProject({
            credential,
            projectPath: projectDirectory,
            resourceType
        });
        cmsResourceId = createdProject.id;
        await addOrUpdateEnvVar(projectDirectory, 'FIGMA_PROJECT_ID', cmsResourceId);
    }
    // Fetch bootstrap info (oauth creds + environments)
    let bootstrapInfo = null;
    let resolvedEnv = null;
    let oauthClientId = null;
    let oauthClientSecret = null;
    if (!options.skipAuth) {
        if (credential) {
            try {
                bootstrapInfo = await getBootstrapInfo(credential, cmsResourceId);
            } catch (error) {
                log.debug(`Control Plane Error: ${error.statusCode} - ${error.message}`);
                if (error instanceof ControlPlaneError && (error.statusCode === 404 || error.statusCode === 410)) {
                    p.log.error(pc.red(getProjectNotFoundMessage({
                        environment: getInfraEnvironment(),
                        projectId: cmsResourceId
                    })));
                    process.exit(1);
                }
                const message = error instanceof Error ? error.message : 'Unknown error';
                p.log.error(pc.red(`✗ Unable to fetch project info for "${cmsResourceId}"`));
                p.log.error(pc.dim(`Details: ${message}`));
                process.exit(1);
            }
            try {
                const envName = options.env ?? process.env.FIGMA_ENVIRONMENT_NAME ?? undefined;
                resolvedEnv = resolveEnvironment({
                    environmentName: envName,
                    environments: bootstrapInfo.environments
                });
                oauthClientId = bootstrapInfo.oauthCredentials.oauthClientId;
                oauthClientSecret = bootstrapInfo.oauthCredentials.oauthClientSecret;
            } catch (error) {
                p.log.error(pc.red(error instanceof Error ? error.message : 'Unknown error'));
                process.exit(1);
            }
        }
    }
    // Step 4: Detect or scaffold project
    if (isInProject && resourceType === 'vite') {
        try {
            await writeProjectConfiguration({
                bootstrapInfo,
                environmentName: resolvedEnv?.name ?? 'production',
                projectDir: process.cwd(),
                projectId: cmsResourceId,
                tokenStore
            });
        } catch (error) {
            p.log.error(error instanceof Error ? error.message : 'Failed to configure project');
            process.exit(1);
        }
        await maybeEnsurePayloadSecret({
            cmsResourceId,
            credential,
            resolvedEnv,
            tokenStore
        });
        p.outro(pc.green('✓ Vite project initialized successfully!'));
        return;
    }
    if (isInProject) {
        // ===== EXISTING PROJECT FLOW =====
        log.debug('Project directory detected');
        // Detect Payload
        const projectInfo = await detectPayloadProject();
        const packageManager = await resolvePackageManager(process.cwd());
        if (projectInfo.hasPayload) {
            // Validate existing Payload version
            if (projectInfo.payloadVersion && !validatePayloadVersion(projectInfo.payloadVersion)) {
                p.log.warn(pc.yellow(`Payload version ${projectInfo.payloadVersion} detected. Version 4.x or newer is required.`));
                p.note('Upgrade to Payload 4.x or newer before continuing', 'Action Required');
                process.exit(1);
            }
            p.log.success(pc.green(`✓ Payload ${projectInfo.payloadVersion || 'detected'}`));
            // Approvals must exist before any install: pnpm v11 aborts on unapproved
            // build scripts, and re-init runs against an existing install.
            await ensurePnpmWorkspace(process.cwd());
            // Check dependencies
            s.start('Checking dependencies...');
            const hasDeps = await hasRequiredDependencies(process.cwd());
            s.stop(pc.green('✓ Dependencies checked'));
            if (!hasDeps) {
                const shouldInstall = await p.confirm({
                    initialValue: true,
                    message: 'Install dependencies now?'
                });
                if (!p.isCancel(shouldInstall) && shouldInstall) {
                    s.start('Installing dependencies...');
                    await installDependencies(process.cwd(), packageManager);
                    s.stop(pc.green('✓ Dependencies installed'));
                }
            }
            s.start('Checking Payload configuration...');
            const modResult = await ensurePayloadFigmaConfig(process.cwd(), packageManager, {
                contentSystemId: resolvedEnv?.contentSystemId ?? cmsResourceId
            });
            if (!modResult.success) {
                s.stop(pc.red('✗ Configuration check failed'));
                displayManualInstructions(modResult.error || 'Unknown error', packageManager);
                process.exit(1);
            }
            if (modResult.modified) {
                s.stop(pc.green('✓ Payload configuration updated'));
                if (modResult.changes.length > 0) {
                    modResult.changes.forEach((change)=>log.debug(pc.dim(` → ${change}`)));
                }
            } else {
                s.stop(pc.green('✓ Payload configuration valid'));
            }
            // Display warnings if any
            if (modResult.warnings && modResult.warnings.length > 0) {
                modResult.warnings.forEach((warning)=>{
                    p.log.warn(pc.yellow(`⚠ ${warning}`));
                });
            }
            // Write environment variables to .env file
            try {
                await addOrUpdateEnvVar(process.cwd(), 'FIGMA_PROJECT_ID', cmsResourceId);
                await addOrUpdateEnvVar(process.cwd(), 'FIGMA_ENVIRONMENT_NAME', resolvedEnv?.name ?? 'production');
                log.debug('Added FIGMA_PROJECT_ID and FIGMA_ENVIRONMENT_NAME to .env file');
                const infraEnv = getInfraEnvironment();
                if (infraEnv !== 'production') {
                    await addOrUpdateEnvVar(process.cwd(), 'FIGMA_INFRA_ENV', infraEnv);
                    log.debug(`Added FIGMA_INFRA_ENV=${infraEnv} to .env file`);
                }
                // Cache all environments in local encrypted store
                if (bootstrapInfo && oauthClientId && oauthClientSecret) {
                    cacheAllEnvironments(tokenStore, cmsResourceId, bootstrapInfo);
                }
            } catch (error) {
                p.log.warn(pc.yellow(`⚠ Failed to update .env file: ${error instanceof Error ? error.message : 'Unknown error'}`));
            }
            const secretCached = await maybeEnsurePayloadSecret({
                cmsResourceId,
                credential,
                resolvedEnv,
                tokenStore
            });
            if (secretCached) {
                await commentOutPayloadSecretInEnv(process.cwd());
            }
        } else {
            p.log.warn(pc.yellow('⚠ Payload was not detected in this project'));
            p.note('Run this command in a directory without an existing project or in an existing Payload project.', 'Action Required');
            process.exit(1);
        }
        // npm leaves node_modules in a transient state after a sequence of
        // add/remove calls; a final install reconciles it so the project is
        // immediately buildable.
        s.start('Reconciling dependencies...');
        try {
            await installDependencies(process.cwd(), packageManager);
            s.stop(pc.green('✓ Dependencies reconciled'));
        } catch (error) {
            s.stop(pc.red('✗ Failed to reconcile dependencies'));
            log.error(error instanceof Error ? error.message : 'Unknown error');
            process.exit(1);
        }
        // Apply Lambda modifications (run.sh, Next.js config, lambda:buildzip script)
        await applyLambdaModifications(process.cwd(), packageManager);
        // Ensure .gitignore has required entries
        await ensureGitignore(process.cwd(), [
            '.env',
            '.env.local',
            'lambda.zip'
        ]);
        await runProjectCodegen({
            packageManager,
            projectDir: process.cwd(),
            spinner: s
        });
        await maybeWriteAgentConfigFiles({
            noAgent: options.noAgent,
            projectDir: process.cwd()
        });
        // Generate project token (unless skipping auth)
        if (!options.skipAuth && resolvedEnv) {
            await generateProjectTokenWithFeedback(tokenStore, resolvedEnv.contentSystemId, s, {
                environmentName: resolvedEnv.name,
                projectId: cmsResourceId
            });
        }
        // Success message for existing project
        p.outro(pc.green('✓ Project initialized successfully!'));
        const nextSteps = [
            `Start development server: \`${getRunCommand(packageManager)} dev\``
        ].filter(Boolean);
        p.note(nextSteps.join('\n'), 'Next Steps');
    } else {
        // ===== NEW PROJECT FLOW =====
        const fullPath = projectDirectory;
        const packageManager = detectPackageManagerFromEnvironment();
        // Modify Payload configuration
        s.start('Checking Payload configuration...');
        const modResult = await ensurePayloadFigmaConfig(fullPath, packageManager, {
            contentSystemId: resolvedEnv?.contentSystemId ?? cmsResourceId
        });
        if (!modResult.success) {
            s.stop(pc.red('✗ Configuration check failed'));
            displayManualInstructions(modResult.error || 'Unknown error', packageManager);
            process.exit(1);
        }
        if (modResult.modified) {
            s.stop(pc.green('✓ Payload configuration updated'));
            if (modResult.changes.length > 0) {
                modResult.changes.forEach((change)=>log.debug(pc.dim(` → ${change}`)));
            }
        } else {
            s.stop(pc.green('✓ Payload configuration valid'));
        }
        // Display warnings if any
        if (modResult.warnings && modResult.warnings.length > 0) {
            modResult.warnings.forEach((warning)=>{
                p.log.warn(pc.yellow(`⚠ ${warning}`));
            });
        }
        // Write environment variables to .env file
        try {
            await addOrUpdateEnvVar(fullPath, 'FIGMA_PROJECT_ID', cmsResourceId);
            await addOrUpdateEnvVar(fullPath, 'FIGMA_ENVIRONMENT_NAME', resolvedEnv?.name ?? 'production');
            log.debug('Added FIGMA_PROJECT_ID and FIGMA_ENVIRONMENT_NAME to .env file');
            const infraEnv = getInfraEnvironment();
            if (infraEnv !== 'production') {
                await addOrUpdateEnvVar(fullPath, 'FIGMA_INFRA_ENV', infraEnv);
                log.debug(`Added FIGMA_INFRA_ENV=${infraEnv} to .env file`);
            }
            // Cache all environments in local encrypted store
            if (bootstrapInfo && oauthClientId && oauthClientSecret) {
                cacheAllEnvironments(tokenStore, cmsResourceId, bootstrapInfo);
            }
        } catch (error) {
            p.log.warn(pc.yellow(`⚠ Failed to update .env file: ${error instanceof Error ? error.message : 'Unknown error'}`));
        }
        const secretCached = await maybeEnsurePayloadSecret({
            cmsResourceId,
            credential,
            resolvedEnv,
            tokenStore
        });
        if (secretCached) {
            await removePayloadSecretFromEnv(fullPath);
        }
        // npm leaves node_modules in a transient state after a sequence of
        // add/remove calls; a final install reconciles it so the project is
        // immediately buildable.
        s.start('Reconciling dependencies...');
        try {
            await installDependencies(fullPath, packageManager);
            s.stop(pc.green('✓ Dependencies reconciled'));
        } catch (error) {
            s.stop(pc.red('✗ Failed to reconcile dependencies'));
            log.error(error instanceof Error ? error.message : 'Unknown error');
            process.exit(1);
        }
        await runProjectCodegen({
            packageManager,
            projectDir: fullPath,
            spinner: s
        });
        await maybeWriteAgentConfigFiles({
            noAgent: options.noAgent,
            projectDir: fullPath
        });
        // Generate project token (unless skipping auth)
        if (!options.skipAuth && resolvedEnv) {
            await generateProjectTokenWithFeedback(tokenStore, resolvedEnv.contentSystemId, s, {
                environmentName: resolvedEnv.name,
                projectId: cmsResourceId
            });
        }
        // Initialize git repository (after all files including lock file are ready)
        initializeGitRepo(fullPath);
        // Success message for NEW project
        p.log.step(pc.bgGreen(pc.black(' Project created successfully! ')));
        const relativePath = path.relative(process.cwd(), fullPath);
        const nextSteps = [];
        // Only show cd command if user needs to navigate
        if (relativePath && relativePath !== '.') {
            nextSteps.push(`cd ${relativePath}`);
        }
        nextSteps.push(`${getRunCommand(packageManager)} dev or follow directions in README.md`, '', 'Documentation:', '- Getting Started: https://payloadcms.com/docs/getting-started/what-is-payload', '- Configuration: https://payloadcms.com/docs/configuration/overview');
        p.note(nextSteps.join('\n'), 'Next Steps');
        p.outro(pc.green('✓ Done'));
    }
}
